package jakarta.validation; import java.util.Collections; import java.util.Set; public class ConstraintViolationException extends RuntimeException { private static final long serialVersionUID=1L; private final transient Set<ConstraintViolation<?>> violations; public ConstraintViolationException(Set<? extends ConstraintViolation<?>> values) { violations=values==null?Collections.<ConstraintViolation<?>>emptySet():Collections.unmodifiableSet(new java.util.LinkedHashSet<ConstraintViolation<?>>(values)); } public Set<ConstraintViolation<?>> getConstraintViolations(){return violations;} }
